"use client";

import { loadFont } from "@remotion/google-fonts/GolosText";
import type React from "react";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_PARTS,
  goalOf,
  type HalfBuiltElementId,
  halfBuiltTimeline,
  toUnits,
  type Unit,
} from "./timeline";

const golos = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface HalfBuiltPart {
  text: string;
  when?: string;
}

export interface HalfBuiltProps {
  parts?: HalfBuiltPart[];
  progress?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the sentence. Load it yourself; Golos Text by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Frames between words as the sentence builds. */
  stagger?: number;
  /** Size of the sentence, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single words, tags and fills, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<HalfBuiltElementId>;
}

const THEMES = {
  dark: { bg: "#1D2B53", ink: "#FFFFFF", accent: "#FFB38A", hollow: 0.62 },
  light: { bg: "#FFF4EC", ink: "#1D2B53", accent: "#D9623B", hollow: 0.55 },
} as const;

const LH = 1.34;
const TAG_EM = 0.22;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_FILL = Easing.bezier(0.45, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const moving = (p: number) => p > 0 && p < 1;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function HalfBuilt(props: HalfBuiltProps) {
  const {
    parts = DEFAULT_PARTS,
    progress = 1.6,
    accent,
    ink,
    background,
    fontFamily = golos.fontFamily,
    fontWeight = 500,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  // The pace that fits the schedule into the clip counts the clip without
  // `speed`, so the schedule gets `durationInFrames`.
  const tl = useTimeline(halfBuiltTimeline, props, durationInFrames, timing);
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const { units, planned } = toUnits(parts);
  const goal = goalOf(planned, progress);
  const t = frame * speed;

  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.08 : 0.07);
  const boxW = W - margin * 2;
  const maxH = H * (portrait ? 0.62 : 0.66);
  const sizeCap = Math.min(H * 0.2, W * (portrait ? 0.16 : 0.12));

  const probeRef = useRef<HTMLDivElement>(null);
  const [handle] = useState(() => delayRender("half-built: measuring"));
  const released = useRef(false);
  const [fontsOk, setFontsOk] = useState(false);
  const [size, setSize] = useState<number | null>(null);

  useEffect(() => {
    let live = true;
    Promise.all([
      golos.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setFontsOk(true);
      });
    return () => {
      live = false;
    };
  }, [fontFamily, fontWeight]);

  useLayoutEffect(() => {
    if (!fontsOk) return;
    const probe = probeRef.current;
    if (!probe) return;
    let s = sizeCap;
    for (let i = 0; i < 60; i++) {
      probe.style.fontSize = `${s}px`;
      if (probe.offsetHeight <= maxH && probe.scrollWidth <= boxW + 1) break;
      s *= 0.96;
    }
    const next = Math.round(s * 10) / 10;
    setSize((prev) => (prev === next ? prev : next));
  });

  useEffect(() => {
    if (size !== null && !released.current) {
      released.current = true;
      continueRender(handle);
    }
  }, [size, handle]);

  // How far each fill goes: whole words up to `progress`, then the rest.
  const amountOf = (plan: number) => Math.min(1, goal - plan);
  const fillOf = (plan: number) => {
    if (plan >= Math.ceil(goal)) return 0;
    const seg = tl.get(`fill:${plan}`);
    return (
      interpolate(t, [seg.start, seg.end], [0, 1], {
        ...CLAMP,
        easing: EASE_FILL,
      }) * amountOf(plan)
    );
  };
  const doneOf = (plan: number) => {
    if (plan >= Math.ceil(goal) || amountOf(plan) < 1) return 0;
    const seg = tl.get(`fill:${plan}`);
    const at = seg.end + seg.beat("settleDelay");
    return interpolate(t, [at, at + seg.beat("settle")], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  const rise = (id: HalfBuiltElementId) => {
    const e = tl.get(id);
    return interpolate(t, [e.start, e.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };

  const font: React.CSSProperties = {
    fontFamily,
    fontWeight,
    lineHeight: LH,
    letterSpacing: "-0.035em",
  };
  const stroke = `${Math.max(1, (size ?? 100) * 0.016).toFixed(2)}px`;

  const renderUnit = (u: Unit, i: number, live: boolean) => {
    const p = live ? rise(`word:${i}`) : 1;
    const style: React.CSSProperties = {
      position: "relative",
      display: "inline-block",
      whiteSpace: "nowrap",
      marginRight: "0.24em",
      opacity: p,
      // Unrounded: a travel snapped to 0.001em stalls and then jumps.
      transform: `translateY(${(1 - p) * 0.28}em)${glide(moving(p))}`,
    };
    if (u.plan < 0) {
      return (
        <span key={u.key} style={{ ...style, color: fg }}>
          {u.text}
        </span>
      );
    }
    const fill = live ? fillOf(u.plan) : 0;
    const done = live ? doneOf(u.plan) : 0;
    const tagP = live ? rise(`tag:${u.plan}`) : 1;
    return (
      <span key={u.key} style={style}>
        <span
          style={{
            color: "transparent",
            WebkitTextStroke: `${stroke} ${fg}`,
            opacity: c.hollow * (1 - done),
          }}
        >
          {u.text}
        </span>
        <span
          aria-hidden
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            color: done > 0 ? fg : hi,
            opacity: 1,
            clipPath: `inset(-20% ${((1 - fill) * 100).toFixed(2)}% -20% -2%)`,
          }}
        >
          <span style={{ color: hi, opacity: 1 - done }}>{u.text}</span>
          <span
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              color: fg,
              opacity: done,
            }}
          >
            {u.text}
          </span>
        </span>
        <span
          style={{
            position: "absolute",
            left: "0.02em",
            bottom: `${((LH - 0.1) / TAG_EM).toFixed(3)}em`,
            fontSize: `${TAG_EM}em`,
            lineHeight: 1,
            letterSpacing: "0em",
            color: hi,
            whiteSpace: "nowrap",
            opacity: tagP * (1 - done),
            transform: `translateY(${(1 - tagP) * 0.5}em)${glide(
              moving(tagP) && !moving(p),
            )}`,
          }}
        >
          {u.when}
        </span>
      </span>
    );
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        ref={probeRef}
        style={{
          ...font,
          position: "absolute",
          left: 0,
          top: 0,
          width: boxW,
          visibility: "hidden",
        }}
      >
        {units.map((u, i) => renderUnit(u, i, false))}
      </div>
      <ScaleLayer scale={scale}>
        <div
          style={{
            ...font,
            position: "absolute",
            left: margin,
            top: "50%",
            width: boxW,
            fontSize: size ?? sizeCap,
            transform: "translateY(-50%)",
            opacity: size === null ? 0 : 1,
          }}
        >
          {units.map((u, i) => renderUnit(u, i, true))}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// Each word of the sentence rising in, the roadmap tag over each planned
// word, and the fills that colour the planned words in up to `progress`.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. When the
// natural schedule runs past the clip, it is compressed to fit (`pace`).
// The ids are public: a saved `timing` prop refers to them.

export type HalfBuiltElementId =
  | `word:${number}`
  | `tag:${number}`
  | `fill:${number}`;

/** One part of the sentence; `when` marks it planned (`HalfBuiltPart`). */
export interface PlanPart {
  text: string;
  when?: string;
}

export interface HalfBuiltTimingProps {
  parts?: PlanPart[];
  progress?: number;
  stagger?: number;
}

export const DEFAULT_PARTS: PlanPart[] = [
  { text: "It cuts," },
  { text: "captions,", when: "Spring" },
  { text: "narrates", when: "Summer" },
  { text: "and" },
  { text: "translates", when: "Later" },
  { text: "your launch film." },
];

export const WORD_GAP = 3;
const RISE = 12;
const TAG_GAP = 5;
const TAG_RISE = 14;
const FILL_FULL = 30;
const FILL_PAUSE = 12;
const SETTLE = 10;
/** A fully filled word settles into the ink this long after its fill. */
const SETTLE_DELAY = 2;

export interface Unit {
  key: string;
  text: string;
  plan: number;
  when?: string;
}

/** The sentence as units: single words, and each planned part whole. */
export function toUnits(parts: PlanPart[]) {
  const units: Unit[] = [];
  let plan = 0;
  parts.forEach((p, pi) => {
    if (p.when !== undefined) {
      units.push({ key: `p${pi}`, text: p.text.trim(), plan, when: p.when });
      plan += 1;
    } else {
      p.text
        .split(/\s+/)
        .filter(Boolean)
        .forEach((w, wi) => {
          units.push({ key: `p${pi}-${wi}`, text: w, plan: -1 });
        });
    }
  });
  return { units, planned: plan };
}

/** How many planned words `progress` fills, clamped to the plan. */
export function goalOf(planned: number, progress: number) {
  return Math.max(0, Math.min(planned, progress));
}

// `word:<i>` is unit `i` (a planned part counts as one unit); `tag:<j>` and
// `fill:<j>` belong to planned unit `j`. Each list is a chain. A fill's
// `settleDelay` and `settle` beats time the hand-over to the ink after it.
// `length` here is the clip length without `speed`, as the pace is counted.
export const halfBuiltTimeline = defineTimeline<
  HalfBuiltElementId,
  HalfBuiltTimingProps
>(
  (
    { parts = DEFAULT_PARTS, progress = 1.6, stagger = WORD_GAP },
    { length },
  ) => {
    const { units, planned } = toUnits(parts);
    const goal = goalOf(planned, progress);
    const wordsIn = 2 + units.length * stagger + 12;
    const tagsAt = Math.max(16, wordsIn - 8);
    const fillAt = tagsAt + planned * TAG_GAP + 14;
    const segments: { start: number; end: number; amount: number }[] = [];
    let cursor = fillAt;
    for (let j = 0; j < Math.ceil(goal); j++) {
      const amount = Math.min(1, goal - j);
      const dur = Math.max(16, FILL_FULL * amount);
      segments.push({ start: cursor, end: cursor + dur, amount });
      cursor += dur + FILL_PAUSE + (amount >= 1 ? SETTLE : 0);
    }
    const naturalEnd = segments.length
      ? segments[segments.length - 1].end + SETTLE
      : fillAt;
    const pace = Math.max(1, (naturalEnd + 30) / Math.max(1, length));

    const planUnits = units.filter((u) => u.plan >= 0);
    const elements: TimelineElement<HalfBuiltElementId>[] = [
      ...units.map(
        (u, i): TimelineElement<HalfBuiltElementId> => ({
          id: `word:${i}`,
          lane: "Words",
          label: u.text,
          start: (2 + i * stagger) / pace,
          length: RISE / pace,
          follows: i > 0 ? `word:${i - 1}` : undefined,
        }),
      ),
      ...planUnits.map(
        (u, j): TimelineElement<HalfBuiltElementId> => ({
          id: `tag:${j}`,
          lane: "Tags",
          label: u.when ?? "",
          start: (tagsAt + j * TAG_GAP) / pace,
          length: TAG_RISE / pace,
          follows: j > 0 ? `tag:${j - 1}` : undefined,
        }),
      ),
      ...segments.map(
        (seg, j): TimelineElement<HalfBuiltElementId> => ({
          id: `fill:${j}`,
          lane: "Fills",
          label: planUnits[j]?.text ?? "",
          start: seg.start / pace,
          length: (seg.end - seg.start) / pace,
          follows: j > 0 ? `fill:${j - 1}` : undefined,
          beats: { settleDelay: SETTLE_DELAY / pace, settle: SETTLE / pace },
        }),
      ),
    ];
    return elements.sort((a, b) => a.start - b.start);
  },
);
